"""Run from the repo root:  python install_connections.py
Adds the Connections page (connect / disconnect a customer, "Paid, not connected"
badge, dashboard tile). Safe to run twice. Edits keep each file's line endings."""
import base64, os, sys

if not os.path.exists(os.path.join('apps', 'core', 'views.py')):
    sys.exit('Run this from the repo root (apps/core/views.py not found).')

def rd(p): return open(p, 'rb').read().decode('utf-8')
def wr(p, s): open(p, 'wb').write(s.encode('utf-8'))
def b64(s): return base64.b64decode(s).decode('utf-8')

NEW_FILES = {
    'apps/core/connections.py': '',
    'templates/core/connections.html': '',
    'apps/core/test_connections.py': '',
}
VIEWS_BLOCK = b64('')
CSS_BLOCK = b64('')

for path, data in NEW_FILES.items():
    wr(path, b64(data)); print('  wrote', path)

# ---- views.py
p = 'apps/core/views.py'; s = rd(p); eol = '\r\n' if '\r\n' in s else '\n'
if 'def connections(' not in s:
    s = s.rstrip('\r\n') + '\n\n\n' + VIEWS_BLOCK.rstrip('\n') + '\n'
if "conn.count('unconnected')" not in s:
    a = "        'lapsed_customers': insights.count('lapsed'),"
    assert a in s, 'dashboard anchor not found'
    s = s.replace(a, a + eol + "        'unconnected_paid': conn.count('unconnected'),", 1)
    a = "    from apps.core import customer_insights as insights" + eol + "    from apps.mikrotik.models import InternetSession"
    assert a in s, 'dashboard import anchor not found'
    s = s.replace(a, "    from apps.core import connections as conn" + eol + a, 1)
if 'connections_unconnected' not in s:
    a = "            'customers_lapsed': _link('core:customer_list', filter='lapsed'),"
    assert a in s, 'tile link anchor not found'
    s = s.replace(a, a + eol + "            'connections_unconnected': _link('core:connections', filter='unconnected'),", 1)
wr(p, s); print('  updated', p)

# ---- urls.py
p = 'apps/core/urls.py'; s = rd(p); eol = '\r\n' if '\r\n' in s else '\n'
if "name='connections'" not in s:
    a = "    path('customers/', views.customer_list, name='customer_list'),"
    assert a in s, 'urls anchor not found'
    s = s.replace(a, a + eol + "    path('connections/', views.connections, name='connections')," + eol
        + "    path('connections/<int:subscription_id>/connect/', views.connection_connect, name='connection_connect')," + eol
        + "    path('connections/<int:subscription_id>/disconnect/', views.connection_disconnect, name='connection_disconnect'),", 1)
wr(p, s); print('  updated', p)

# ---- sidebar link + styles
p = 'templates/core/admin_base.html'; s = rd(p); eol = '\r\n' if '\r\n' in s else '\n'
if "core:connections" not in s:
    a = """      <a href="{% url 'core:subscriptions' %}" class="{% if request.resolver_match.url_name == 'subscriptions' %}active{% endif %}">Subscriptions</a>"""
    assert a in s, 'nav anchor not found'
    s = s.replace(a, a + eol + """      <a href="{% url 'core:connections' %}" class="{% if request.resolver_match.url_name == 'connections' %}active{% endif %}">Connections</a>""", 1)
if '.conn-actions' not in s:
    a = "  .pager { display: flex;"
    assert a in s, 'css anchor not found'
    s = s.replace(a, CSS_BLOCK.replace('\n', eol) + a, 1)
wr(p, s); print('  updated', p)

# ---- dashboard tile
p = 'templates/core/dashboard.html'; s = rd(p); eol = '\r\n' if '\r\n' in s else '\n'
if 'Paid, not connected' not in s:
    a = """  {% include "core/_stat_tile.html" with icon="bi-clock-history" tone="amber" label="Lapsed Customers" value=lapsed_customers href=tile_links.customers_lapsed %}"""
    assert a in s, 'dashboard tile anchor not found'
    s = s.replace(a, a + eol + """  {% include "core/_stat_tile.html" with icon="bi-wifi-off" tone="red" label="Paid, not connected" value=unconnected_paid href=tile_links.connections_unconnected %}""", 1)
wr(p, s); print('  updated', p)

print('Done. Commit apps/core, templates/core, then push.')